import js from '@eslint/js'
import globals from 'globals'
import reactHooks from 'eslint-plugin-react-hooks'
import tseslint from 'typescript-eslint'
import { defineConfig, globalIgnores } from 'eslint/config'

export default defineConfig([
  globalIgnores([
    'dist',
    'coverage',
    // Extracted fenced code blocks from the docs corpus, regenerated by
    // `tests/docs` on every run (see that project's own test) -- not
    // authored source. Named `__snippet__`, deliberately not a real
    // component or hook, so react-hooks' naming/rules-of-hooks checks
    // don't apply to them.
    'tests/docs/.generated',
  ]),
  {
    files: ['**/*.{ts,tsx}'],
    extends: [js.configs.recommended, tseslint.configs.recommended, reactHooks.configs.flat.recommended],
    languageOptions: {
      ecmaVersion: 2020,
      globals: { ...globals.browser, ...globals.node },
    },
    rules: {
      // Leading-underscore is this codebase's existing convention for a
      // deliberately-unused binding (an interface-mandated parameter, a
      // destructured field discarded via rest spread) -- recognize it
      // instead of flagging every instance.
      '@typescript-eslint/no-unused-vars': [
        'error',
        { argsIgnorePattern: '^_', varsIgnorePattern: '^_', destructuredArrayIgnorePattern: '^_' },
      ],
      // `refs`, `set-state-in-effect`, and `immutability` are React
      // Compiler-safety rules -- new in this plugin major, and this
      // package doesn't opt into the compiler. Turned on cold, they
      // flag ~50 sites across the SDK's internal hook implementations
      // (ref-based render counters, imperative snapshot caching,
      // capture-pattern test doubles) that are established, deliberate
      // patterns in a hand-written hooks library, not bugs -- auditing
      // each one against actual compiler-safety risk is real, separate
      // work (tracked in docs/planning/), not something to wave through
      // silently while wiring up lint. `rules-of-hooks` and
      // `exhaustive-deps` -- the well-established, low-false-positive
      // rules -- stay on.
      'react-hooks/refs': 'off',
      'react-hooks/set-state-in-effect': 'off',
      'react-hooks/immutability': 'off',
    },
  },
])
